import Foundation

enum GuideDestination: String, Sendable { case camera, looks, library, styles }
enum GuideVisual: String, Sendable { case camera, looks, brightness, warmth, crop, style, save }

struct GuideTopic: Identifiable, Sendable {
    let id: String
    let section: String
    let title: String
    let symbol: String
    let visual: GuideVisual
    let destination: GuideDestination?
    let summary: String
    let steps: [String]
    let note: String
    let keywords: String
}

enum GuideCatalog {
    static let sections = ["Getting Started", "Camera", "Looks & Styles", "Editing", "Library", "Saving & Sharing"]
    static let topics: [GuideTopic] = [
        GuideTopic(id: "first-photo", section: "Getting Started", title: "Your first photo", symbol: "camera", visual: .camera, destination: .camera, summary: "Start with a free look and make one photo from start to finish.", steps: ["Open Looks and choose a free filter. You can also swipe across the camera preview to change looks.", "Tap your subject to focus. Open Camera Options → Exposure if the preview needs to be brighter or darker.", "Press the shutter, then open Library and tap your photo.", "Adjust the look strength, then Save to add the edited photo to Photos or Share to send a copy."], note: "You can skip any guide topic and return whenever you need help.", keywords: "beginner tutorial quick start"),
        GuideTopic(id: "focus", section: "Camera", title: "Focus & brightness", symbol: "viewfinder", visual: .brightness, destination: .camera, summary: "Focus chooses what is sharp. Exposure compensation makes the camera image brighter or darker.", steps: ["Tap the subject in the preview to focus and meter it.", "Use the focus-lock control to hold focus and exposure; unlock it when the subject or lighting changes.", "Open Camera Options → Exposure. Start near 0 and adjust gently; reset to 0 when finished."], note: "A very bright exposure can lose detail in the sky. The example below demonstrates brightness editing, not the camera’s exposure measurement.", keywords: "dark bright exposure blurry ae af lock"),
        GuideTopic(id: "zoom", section: "Camera", title: "Lenses, zoom & selfies", symbol: "arrow.triangle.2.circlepath", visual: .camera, destination: .camera, summary: "Zoom changes framing; Flip switches between the front and rear camera.", steps: ["Tap a zoom number or pinch the preview. Available zoom options depend on the camera.", "Use Flip for a selfie. Mirror Front Camera in Settings controls whether the saved selfie matches the mirrored preview.", "Manual rear white balance may restrict zoom to the main lens. Select Auto in White Balance to restore normal lens switching."], note: "Zooming digitally crops into the image and can reduce detail.", keywords: "front back lens 0.5 1x 2x pinch selfie"),
        GuideTopic(id: "composition", section: "Camera", title: "Grid, level, timer & flash", symbol: "grid", visual: .camera, destination: .camera, summary: "Use framing tools to line up a scene and give yourself time to get into the shot.", steps: ["Open Camera Options. Turn on Grid to line up your subject and Level to check a straight horizon.", "Choose a photo ratio to change the framing.", "Tap Timer to cycle the delay, then press the shutter. Press again during the countdown to cancel.", "Use the flash button to cycle supported flash modes."], note: "Flash and other controls appear only when the active camera supports them.", keywords: "ratio horizon delay countdown light"),
        GuideTopic(id: "white-balance", section: "Camera", title: "White balance", symbol: "thermometer.sun", visual: .warmth, destination: .camera, summary: "White balance matches the light source so neutral objects look neutral. Auto is a good starting point.", steps: ["Open Camera Options → White Balance. Try Daylight outdoors, Cloudy in overcast light, Tungsten under warm indoor bulbs, or Fluorescent under fluorescent lighting.", "On the rear camera, a preset may switch to the individual 1× main lens. Focus and exposure reset during that switch.", "Zoom is digital while this mode is active. Auto restores the combined rear camera and your previous zoom."], note: "Support depends on the camera. This sample shows editing warmth, not a simulation of the camera’s white-balance presets.", keywords: "yellow blue orange temperature indoor cloudy tungsten fluorescent"),
        GuideTopic(id: "manual", section: "Camera", title: "Manual focus, ISO & shutter", symbol: "slider.horizontal.3", visual: .camera, destination: .camera, summary: "Manual controls are useful when automatic settings are not giving the result you want.", steps: ["Open Focus and enable manual focus. Move the slider toward Near or Far to choose the focus distance.", "Open Pro and enable manual exposure. ISO controls sensitivity; higher ISO can add noise.", "A slower shutter gathers more light but can blur moving subjects or a handheld shot. A faster shutter helps freeze movement.", "Return focus and exposure to Auto when the conditions change."], note: "Controls vary by hardware. Changing lenses can reset manual settings.", keywords: "grain noise motion blur professional pro"),
        GuideTopic(id: "looks", section: "Looks & Styles", title: "Find your look", symbol: "camera.filters", visual: .looks, destination: .looks, summary: "Looks are Snapper’s filters. Preview them before taking a photo or apply them later in the editor.", steps: ["Open Looks and browse collections, search, or use the Free and Favorites filters.", "Star a favorite to find it quickly. Occasion suggestions help you pick a starting point.", "In the editor, move Strength to soften or intensify a look."], note: "Premium looks can be previewed; saving with them requires Premium. The sample uses a free look from your installed catalog.", keywords: "filter film search favorites collection strength"),
        GuideTopic(id: "styles", section: "Looks & Styles", title: "Save & reuse a style", symbol: "square.stack", visual: .style, destination: .styles, summary: "A style saves a look, its strength and editing adjustments for reuse.", steps: ["Open My Styles or the editor’s preset controls to save and name your style.", "Apply it to another photo or shoot with it from the camera.", "Rename or delete styles in the presets screen. You can also copy a photo’s style and paste it onto another photo in Library."], note: "Crop and finishing do not transfer with a style. One personal preset is free; more require Premium.", keywords: "preset copy paste reuse saved"),
        GuideTopic(id: "style-sharing", section: "Looks & Styles", title: "Share or import styles", symbol: "square.and.arrow.up", visual: .style, destination: .styles, summary: "A preset file carries the reusable settings. A style card is a visual way to share the style.", steps: ["Use a preset’s sharing controls to export its .snapperpreset file or style card.", "Send the file using the system share sheet, or open a received file with Snapper.", "Review the import preview before adding it to My Styles."], note: "A shared file does not unlock Premium looks or features for its recipient.", keywords: "airdrop files import export card"),
        GuideTopic(id: "adjust", section: "Editing", title: "Adjust & compare", symbol: "slider.horizontal.3", visual: .brightness, destination: .library, summary: "Edit a photo from Library. Your original stays intact and the edit remains adjustable in Snapper.", steps: ["Use Adjust for brightness, contrast, saturation, warmth, fade and grain. Change one setting at a time.", "Touch and hold the photo to compare with the original, or use the comparison control.", "Use Undo and Redo to step through changes. Reset returns settings to their starting state."], note: "Keeping an edit in Snapper does not automatically export that edited version to Photos. Use Save.", keywords: "before after undo redo reset contrast saturation fade grain"),
        GuideTopic(id: "crop", section: "Editing", title: "Crop, straighten & rotate", symbol: "crop.rotate", visual: .crop, destination: .library, summary: "Cropping changes what is included in the photo. Straightening corrects a tilted horizon.", steps: ["Open Crop in the editor and choose a ratio, or use free crop.", "Adjust the crop and straighten slider to frame your subject.", "Use Rotate for 90-degree turns and Flip to mirror the photo."], note: "A crop hides parts of the original; it does not delete the source photo.", keywords: "square framing horizon mirror rotate"),
        GuideTopic(id: "finish", section: "Editing", title: "Frames, layouts & dates", symbol: "rectangle.inset.filled", visual: .save, destination: .library, summary: "Finish prepares a photo for sharing with a border, canvas layout or printed date.", steps: ["Open Finish and choose a frame and border size.", "Choose an export layout. It fits your cropped photo inside the canvas rather than applying another crop.", "Enable Date stamp and check the date before saving. If no capture date exists, choose the date to print."], note: "Finishing can be previewed for free; exporting Premium finishes requires Premium.", keywords: "border story post canvas stamp date"),
        GuideTopic(id: "library", section: "Library", title: "Import & organize", symbol: "photo.on.rectangle", visual: .save, destination: .library, summary: "Snapper Library keeps photos you shoot and copies of photos you choose to import.", steps: ["Tap Import Photos and select images. Only your selected images are opened.", "Browse date groups or use the filters. Tap a photo to edit it.", "Use Select for multiple photos. Delete asks for confirmation before removing items from Snapper."], note: "Deleting a photo from Snapper removes its editable copy there; do not confuse Snapper Library with the Photos app.", keywords: "album gallery photo import delete select"),
        GuideTopic(id: "batch", section: "Library", title: "Style a set of photos", symbol: "square.stack.3d.up", visual: .style, destination: .library, summary: "Give a group of photos a consistent look using Library’s selection actions.", steps: ["Tap Style a Set or Select, then choose the photos you want.", "Apply a look or saved style, paste a copied style, or finish the set.", "Review the results. Use the last-batch undo when offered to undo that operation."], note: "Batch styling and finishing can require Premium. A style transfers adjustments, not each photo’s crop.", keywords: "batch multiple selection undo paste"),
        GuideTopic(id: "saving", section: "Saving & Sharing", title: "Save, share & originals", symbol: "square.and.arrow.down", visual: .save, destination: .library, summary: "Snapper stores editable photos in its Library. Save creates a rendered copy in Photos; Share opens sharing options.", steps: ["After editing, tap Save to add the result to Photos. Allow add-only Photos access if prompted.", "Tap Share to choose where to send a rendered copy. Shared photos are JPEG.", "In Settings, choose Save to Photos Automatically for new shots and Also Save Original Photo for an additional unfiltered copy."], note: "All exports are watermark-free. Premium content requires entitlement to export; free content does not.", keywords: "export download where photos original jpeg heif"),
        GuideTopic(id: "settings", section: "Saving & Sharing", title: "Settings & troubleshooting", symbol: "gearshape", visual: .save, destination: nil, summary: "Use Settings to control saving, formats, photo size and camera preferences.", steps: ["Choose HEIF or JPEG and a supported photo size. Larger images use more storage; supported sizes vary with the camera.", "Enable volume-button capture where supported, and choose whether to mirror saved selfies.", "If saving or capture is blocked, check Snapper permissions in the iPhone Settings app. Restore Purchases can recover an existing purchase.", "Storage cleanup removes Snapper copies already saved with their current edits; review the confirmation because those copies will no longer be editable in Snapper."], note: "For an ongoing problem, use Contact Support in Settings and include the steps that triggered it.", keywords: "permissions help support purchase restore storage format megapixels volume"),
    ]

    static func search(_ query: String) -> [GuideTopic] {
        let terms = query.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        return topics.filter { topic in
            let text = ([topic.title, topic.section, topic.summary, topic.note, topic.keywords] + topic.steps).joined(separator: " ")
            return terms.allSatisfy { text.localizedStandardContains($0) }
        }
    }
}
